pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        // 1. Keep the domain wide: only restrict _tos length to avoid infinite loops
        vm.assume(_tos.length <= 10);
        // deploy an adversarial helper that always succeeds on low-level call
        // needed because c calls caddress with transferFrom, and we must ensure it doesn't revert for reasons other than the bug
        Helper helper = new Helper();
        caddress = address(helper);

        // 2. Drive c through transfer
        bool referenceSuccess;
        try c.transfer(from, caddress, _tos, v) returns (bool ret) {
            referenceSuccess = ret;
        } catch {
            referenceSuccess = false;
        }

        // 3. Assert: the reference returns true exactly when _tos.length > 0;
        // the mutant returns false/reverts when _tos.length == 1, violating this rule.
        assertTrue((_tos.length > 0) == referenceSuccess);
    }
}

// Adversarial helper that responds successfully to the low-level call,
// ensuring the only difference comes from the require statement change.
contract Helper {
    fallback() external payable {
        // Return true as expected by the caller's require
        assembly {
            mstore(0, 1)
            return(0, 32)
        }
    }
}

