pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 v) public {
        // admissible domain: v can be anything, no restriction
        // construct an empty array
        address[] memory empty;
        // wrap the call; P reverts, M does not revert and returns true
        bool success;
        try c.transfer(address(0x1), address(0x2), empty, v) returns (bool ret) {
            // if no revert, success = true, but we also check return value below
            success = true;
        } catch {
            success = false;
        }
        // General rule: the call MUST revert when _tos is empty.
        // In P, the require(_tos.length > 0) causes revert => success == false.
        // In M, the loop does nothing and returns true => success == true.
        assertTrue(!success);
    }
}

