import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _tos0, uint8 _len, uint v) public {
        vm.assume(_len > 0);
        address[] memory tos = new address[](_len);
        for (uint i = 0; i < _len; i++) {
            tos[i] = _tos0;
        }
        // The adversarial counterparty: a contract that exposes a counter of how many times transferFrom was called
        Counterparty counterparty = new Counterparty();
        vm.prank(address(this));
        c.transfer(address(this), address(counterparty), tos, v);
        // The rule: the number of processed transfers must equal _tos.length (all elements processed)
        assertTrue(counterparty.count() == _len);
    }
}

contract Counterparty {
    uint public count;
    function transferFrom(address, address, uint256) external returns (bool) {
        count++;
        return true;
    }
}

