pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address[] memory _tos, uint v) public {
        // Assume non-zero recipient list to satisfy length check
        vm.assume(_tos.length > 0);
        // Assume from is not the zero address and has no code (fuzzer gives EOA)
        vm.assume(from != address(0));
        // Assume addresses in _tos have no code to keep the call succeeding is not the point
        // We need a helper that reverts on transferFrom. We deploy one and use it as caddress.
        // caddress is the adversarial party.
        FailingToken ft = new FailingToken();
        bool ok;
        try c.transfer(from, address(ft), _tos, v) returns (bool result) {
            ok = result;
        } catch {
            ok = false;
        }
        // The reference C must revert (ok == false) because the external call to FailingToken always reverts.
        // The buggy version neither checks return nor reverts, so it will succeed (ok == true).
        assertTrue(!ok, "Reference must revert, bug does not");
    }
}

contract FailingToken {
    fallback() external payable {
        revert("transferFrom failed");
    }
}

